<script>
  import {onMount} from 'svelte';
  import {networkContains, ruleIsActive} from './firewall.js';
  import ServicePipeline from './ServicePipeline.svelte';
  export let api;
  export let snapshot;
  export let management=[];
  let services=[],templates=[],draft=null,detail=null,tab='Overview',error='',notice='',busy=false;
  let sourceId='',sample='',spacing=1,result=null,playError='',playBusy=false,simulation=null;
  let selection=null,selectedEvent=null,deleteArmed=false,playTimer,playVersion=0,loaded=false;
  const tabs=['Overview','Sources & Filters','Detection Policies','Decisions & Bans','Settings'];
  const uid=()=>globalThis.crypto?.randomUUID?.()?.slice(0,8)||Math.random().toString(36).slice(2,10);
  const time=s=>s?new Date(s*1000).toLocaleString():'—';
  const copy=v=>structuredClone(v);
  const blank=()=>({id:0,revision:0,name:'New service',description:'',enabled:true,observe_only:true,scope:'source_ip',sources:[],policies:[]});
  const filter=()=>({id:uid(),name:'Log filter',enabled:true,patterns:['(?P<source_ip>[0-9a-fA-F:.]+)'],event_type:'authentication_failure',ip_capture:'source_ip',subject_capture:null,timestamp_capture:null});
  const policy=()=>({id:uid(),name:'Repeated failures',enabled:true,observe_only:true,event_types:['authentication_failure'],threshold:5,window_seconds:300,ban_seconds:600,ban_escalation:null});
  async function refresh(){try{services=await api('/services');}catch(e){error=e.message;}}
  async function open(id){error='';notice='';deleteArmed=false;busy=true;try{detail=await api(`/services/${id}`);draft=copy(detail.service);tab='Overview';sourceId=draft.sources[0]?.id||'';selection=null;selectedEvent=null;result=null;simulation=null;}catch(e){error=e.message;}finally{busy=false;}}
  async function refreshDetail(){if(!draft?.id)return;const id=draft.id;try{const value=await api(`/services/${id}`);if(draft?.id===id)detail=value;}catch(e){error=e.message;}}
  function create(service=blank()){draft=copy(service);draft.id=0;draft.revision=0;draft.observe_only=true;detail=null;tab='Settings';sourceId=draft.sources[0]?.id||'';result=null;simulation=null;selection=null;error='';notice='';}
  async function save(){busy=true;error='';notice='';try{draft=await api(draft.id?`/services/${draft.id}`:'/services',draft.id?'PUT':'POST',draft);await refresh();await refreshDetail();notice='Service saved. Policy evidence restarts with a full warm-up window.';}catch(e){error=e.message;}finally{busy=false;}}
  async function toggle(service){busy=true;error='';try{await api(`/services/${service.id}`,'PUT',{...service,enabled:!service.enabled});await refresh();if(draft?.id===service.id)await open(service.id);}catch(e){error=e.message;}finally{busy=false;}}
  async function remove(){if(!deleteArmed){deleteArmed=true;return;}busy=true;error='';try{await api(`/services/${draft.id}`,'DELETE');draft=null;await refresh();notice='Service deleted. Existing attributed bans remain until expiry; remove individual rules in Firewall if needed.';}catch(e){error=e.message;}finally{busy=false;}}
  function addSource(){const id=uid();draft.sources=[...draft.sources,{id,name:'Log source',enabled:true,input:{kind:'file',path:''},filters:[filter()]}];sourceId=id;}
  function selectNode(node){selection=node;if(node.source)sourceId=node.source;else if(node.type==='source')sourceId=node.id;}
  function editNode(){tab=selection.type==='policy'?'Detection Policies':['source','filter'].includes(selection.type)?'Sources & Filters':'Settings';}
  async function recent(source){playError='';playBusy=true;try{const response=await api('/services/preview','POST',{source});sourceId=source.id;sample=response.lines.join('\n');notice=response.timing;}catch(e){playError=e.message;}finally{playBusy=false;}}
  function schedulePlay(service,source,input,interval){
    clearTimeout(playTimer);const version=++playVersion;
    result=null;playError='';if(!service||!source||!input){playBusy=false;return;}
    playTimer=setTimeout(async()=>{playBusy=true;try{const value=await api('/services/playground','POST',{service,source_id:source,input,spacing_seconds:Number(interval)});if(version===playVersion)result=value;}catch(e){if(version===playVersion)playError=e.message;}finally{if(version===playVersion)playBusy=false;}},400);
  }
  $: if(loaded) schedulePlay(draft?JSON.parse(JSON.stringify(draft)):null,sourceId,sample,spacing);
  async function historical(){busy=true;error='';const config=JSON.stringify(draft);try{const value=await api(`/services/${draft.id}/history-simulation`,'POST',draft);if(config===JSON.stringify(draft))simulation={...value,config};}catch(e){error=e.message;}finally{busy=false;}}
  $: if(simulation && simulation.config!==JSON.stringify(draft))simulation=null;
  $: dirty=!!detail && JSON.stringify(draft)!==JSON.stringify(detail.service);
  $: visibleHealth=Object.fromEntries((draft?.sources||[]).map(source=>[source.id,!dirty&&detail?.source_health[source.id]?.revision===draft.revision?detail.source_health[source.id]:{status:dirty?'Unsaved configuration':'Configuration changed / waiting'}]));
  function allowed(ip){return management.some(n=>networkContains(n,ip))||(snapshot?.rules||[]).some(r=>r.kind==='allow'&&ruleIsActive(r,Math.floor(Date.now()/1000))&&networkContains(r.network,ip));}
  async function resetSource(source){busy=true;error='';try{await api(`/services/${draft.id}/sources/${source.id}/reset`,'POST');await open(draft.id);notice='Reading position reset to current logs. Policy warm-up restarted.';}catch(e){error=e.message;}finally{busy=false;}}
  function decisionStatus(d){if(d.rule){if(!d.rule.enabled)return 'Removed';if(d.rule.expires&&d.rule.expires<=Date.now()/1000)return 'Expired';if(d.rule.error)return 'Enforcement failed';if(d.rule.applied&&snapshot?.blocking)return allowed(d.hit.source_ip)?'Applied rule · allowlist override':'Active ban';return 'Rule retained / not applied';}return ({observe_only:'Detection · observe only',global_observe:'Decision · global observe',allowlisted:'Decision · allowlisted',incomplete_evidence:'Decision · warm-up / incomplete',health_suspended:'Decision · health suspended',already_active:'Decision · existing policy ban'})[d.status]||d.status;}
  onMount(()=>{loaded=true;Promise.all([refresh(),api('/services/templates').then(v=>templates=v)]).catch(e=>error=e.message);const timer=setInterval(refreshDetail,5000);return()=>{clearTimeout(playTimer);clearInterval(timer);playVersion++;};});
</script>
<div class="services">
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
  <div class="toolbar"><button onclick={()=>{draft=null;refresh();}}>All services</button><button onclick={()=>create()}>Create service</button>{#each templates as template}<button onclick={()=>create(template.service)}>Use {template.name} template</button>{/each}</div>
  {#if !draft}
    <section class="panel"><div class="title"><h2>Protected services</h2><button onclick={refresh}>Refresh</button></div><p class="help">Detection and enforcement are configured separately. New services start in observe-only mode.</p><div class="scroll"><table><thead><tr><th>Service</th><th>Detection</th><th>Enforcement request</th><th>Pipeline</th><th></th></tr></thead><tbody>{#each services as service}<tr><td><button class="link" onclick={()=>open(service.id)}>{service.name}</button><small>{service.description}</small></td><td>{service.enabled?'Enabled':'Disabled'}</td><td>{service.observe_only?'Observe only':'Per policy · global safeguards apply'}</td><td>{service.sources.length} sources / {service.policies.length} policies</td><td><button disabled={busy} onclick={()=>toggle(service)}>{service.enabled?'Disable':'Enable'}</button></td></tr>{/each}{#if !services.length}<tr><td colspan="5">No services yet. Start with the editable OpenSSH template or create a service.</td></tr>{/if}</tbody></table></div></section>
  {:else}
    <div class="toolbar"><h2>{draft.name}</h2><span class="badge">{draft.id?'Editable configuration':'Unsaved service'}</span><span class="badge">{draft.observe_only?'Observe only':'Enforcement requested'}</span><button class="primary" disabled={busy} onclick={save}>Save service</button><button disabled={busy||!draft.id} onclick={refreshDetail}>Refresh health & history</button></div>
    {#if dirty}<p class="notice">Unsaved changes. Saved settings remain active until you save this service.</p>{/if}
    <nav aria-label="Service detail">{#each tabs as item}<button class:active={tab===item} onclick={()=>tab=item}>{item}</button>{/each}</nav>
    {#if tab==='Overview'}
      <section class="panel"><div class="title"><h2>Service pipeline</h2><span class="badge">Generated from current configuration</span></div><p class="help">Select a node to inspect it. Dashed nodes are disabled; amber sources need attention. Save edits to activate them.</p><ServicePipeline service={draft} health={visibleHealth} replay={simulation?.simulation||null} selected={selectedEvent} onselect={selectNode} blocking={snapshot?.blocking} automatic={snapshot?.automatic}/>
        {#if selection}<div class="inspect"><strong>{selection.type==='enforcement'?'Global enforcement':selection.type} configuration</strong><pre>{JSON.stringify(selection.type==='source'?draft.sources.find(s=>s.id===selection.id):selection.type==='filter'?draft.sources.find(s=>s.id===selection.source)?.filters.find(f=>f.id===selection.id):selection.type==='policy'?draft.policies.find(p=>p.id===selection.id):{enabled:draft.enabled,observe_only:draft.observe_only,scope:draft.scope,global_automatic:snapshot?.automatic,global_blocking:snapshot?.blocking},null,2)}</pre><button onclick={editNode}>Edit configuration</button>{#if selection.type==='enforcement'}<a href="#firewall">Open global Firewall settings ↗</a>{/if}</div>{/if}
      </section>
      <section class="panel"><div class="title"><h2>Historical replay</h2><button disabled={busy||!draft.id} onclick={historical}>Estimate potentially preventable entries</button></div><p class="help">Replay retained normalized events against the current policies. Filters are not reapplied to historical text. Counts later events from an IP during a hypothetical ban window. This is an estimate, not proof of prevented attacks.</p>{#if simulation}<div class="inspect"><strong>{simulation.simulation.potentially_preventable} potentially preventable log events</strong><p>{simulation.simulation.decisions.length} threshold decisions · {time(simulation.from)} to {time(simulation.to)}{simulation.limited?' · Replay sample limit reached':''}</p><p>{simulation.caveat}</p></div>{/if}</section>
      <section class="panel"><div class="title"><h2>Source health</h2></div>{#each draft.sources as source}<div class="health"><strong>{source.name}</strong><span class="badge">{!source.enabled||!draft.enabled?'Disabled':visibleHealth[source.id]?.status||'Waiting for collection'}</span><small>{detail?.source_health[source.id]?.entries||0} entries read · {time(detail?.source_health[source.id]?.updated)}</small>{#if visibleHealth[source.id]?.error}<p class="warning">{visibleHealth[source.id].error}</p>{#if draft.id}<button disabled={busy} onclick={()=>resetSource(source)}>Reset reading position to current logs</button>{/if}{/if}</div>{/each}</section>
      <section class="panel"><div class="title"><h2>Recent normalized detections</h2><small>Select an event to highlight its pipeline path.</small></div><div class="scroll"><table><thead><tr><th>Time</th><th>IP / subject</th><th>Event</th><th>Source / filter</th><th>Evidence</th></tr></thead><tbody>{#each detail?.events||[] as row}<tr><td>{time(row.event.at)}<small>{row.event.timestamp_origin} time</small></td><td>{row.event.source_ip}<small>{row.event.subject||'—'}</small></td><td><button class="link" onclick={()=>{selectedEvent=row.event;selection={type:'filter',id:row.event.filter_id,source:row.event.source_id};}}>{row.event.event_type}</button></td><td>{row.event.source_id} / {row.event.filter_id}</td><td class="evidence">{row.event.evidence}</td></tr>{/each}</tbody></table></div><p class="help">Latest 200 events. An event is evidence; a policy threshold creates a decision; an applied rule is an active ban.</p></section>
    {:else if tab==='Sources & Filters'}
      <div class="toolbar"><button disabled={draft.sources.length>=8} onclick={addSource}>Add source</button><small>Allowed file roots: {detail?.access.allowed_roots.join(', ')||'Operator must configure service_logs.allowed_roots'}. Journal: {detail?.access.journal_directory||'Operator must configure journal access'}.</small></div>
      {#each draft.sources as source,si}
        <section class="panel"><div class="title"><h2>{source.name}</h2><button onclick={()=>{draft.sources=draft.sources.filter((_,i)=>i!==si);if(sourceId===source.id)sourceId=draft.sources[0]?.id||'';}}>Remove source</button></div><div class="form-grid"><label>Name<input bind:value={source.name} maxlength="128"/></label><label>Input<select value={source.input.kind} onchange={e=>{source.input=e.currentTarget.value==='file'?{kind:'file',path:''}:{kind:'journal',unit:'ssh.service'};draft={...draft};}}><option value="file">Plain-text file</option><option value="journal">Systemd journal</option></select></label><label class="check"><input type="checkbox" bind:checked={source.enabled}/> Source enabled</label>{#if source.input.kind==='file'}<label>Absolute path<input bind:value={source.input.path} placeholder="/host/logs/auth.log"/></label>{:else}<label>Systemd unit<input bind:value={source.input.unit} placeholder="ssh.service or sshd.service"/></label>{/if}<button disabled={playBusy} onclick={()=>recent(source)}>Load recent logs into playground</button></div>
          {#each source.filters as f,fi}<div class="filter"><div class="toolbar"><strong>{f.name}</strong><button onclick={()=>{source.filters=source.filters.filter((_,i)=>i!==fi);draft={...draft};}}>Remove filter</button></div><div class="form-grid"><label>Filter name<input bind:value={f.name}/></label><label>Event type<input bind:value={f.event_type}/></label><label>Source IP capture<input bind:value={f.ip_capture}/></label><label>Subject capture (optional)<input value={f.subject_capture||''} oninput={e=>{f.subject_capture=e.currentTarget.value||null;draft={...draft};}}/></label><label>Timestamp capture (optional)<input value={f.timestamp_capture||''} oninput={e=>{f.timestamp_capture=e.currentTarget.value||null;draft={...draft};}}/><small>Unix seconds or RFC3339; otherwise journal / observation time.</small></label><label class="check"><input type="checkbox" bind:checked={f.enabled}/> Filter enabled</label><label class="wide">Regex patterns · one per line<textarea rows="4" spellcheck="false" value={f.patterns.join('\n')} oninput={e=>{f.patterns=e.currentTarget.value.split('\n');draft={...draft};}}></textarea><small>Rust regex syntax, e.g. (?P&lt;source_ip&gt;[0-9a-fA-F:.]+). First matching pattern per filter wins.</small></label></div></div>{/each}
          <button class="add" disabled={source.filters.length>=8} onclick={()=>{source.filters=[...source.filters,filter()];draft={...draft};}}>Add filter</button>
        </section>
      {/each}
      <section class="panel"><div class="title"><h2>Interactive filter & policy playground</h2><span class="badge">Side-effect-free · Rust evaluator</span></div><div class="form-grid"><label>Source<select bind:value={sourceId}>{#each draft.sources as s}<option value={s.id}>{s.name}</option>{/each}</select></label><label>Synthetic seconds between lines<input type="number" min="0" max="3600" bind:value={spacing}/></label><label class="wide">Sample log entries<textarea rows="8" bind:value={sample} maxlength="131072" spellcheck="false" placeholder="Paste one log entry per line. Results update as you edit samples and patterns."></textarea></label></div>{#if playBusy}<p class="help">Evaluating…</p>{/if}{#if playError}<p class="warning" role="alert">{playError}</p>{/if}
        {#if result}<p class="help">{result.timing}</p><div class="scroll"><table><thead><tr><th>Line</th><th>Result</th><th>Filter / pattern</th><th>Source IP / subject</th><th>Normalized event or extraction error</th></tr></thead><tbody>{#each result.matches as match}<tr class:muted={match.status==='ignored'}><td>{match.line}</td><td><span class="badge" class:warning={match.status==='extraction_failed'}>{({matched:'Matched',ignored:'Ignored',extraction_failed:'Extraction failed'})[match.status]}</span></td><td>{match.filter_id} / {match.pattern===null?'—':match.pattern+1}</td><td>{match.event?.source_ip||'—'}<small>{match.event?.subject||''}</small></td><td><details><summary>{match.error||match.event?.event_type||'No event'}</summary><pre>{JSON.stringify(match.event,null,2)}</pre></details></td></tr>{/each}</tbody></table></div><div class="inspect"><h3>Policy simulation</h3><p>{Object.entries(result.counts).map(([ip,count])=>`${ip}: ${count} events`).join(' · ')||'No extracted events'}</p>{#each result.decisions as hit}<p class="danger">Would ban {hit.source_ip} · {hit.policy_name} · {hit.count} events / {hit.window_seconds}s · {hit.ban_seconds}s ban {hit.observe_only?'(service or policy is observe-only; no live ban)':''}</p>{/each}{#if !result.decisions.length}<p>No threshold reached.</p>{/if}</div>{/if}
      </section>
    {:else if tab==='Detection Policies'}
      <div class="toolbar"><button disabled={draft.policies.length>=16} onclick={()=>draft.policies=[...draft.policies,policy()]}>Add policy</button><small>Each policy independently counts matching events per source IP over a rolling window.</small></div>
      {#each draft.policies as p,i}<section class="panel"><div class="title"><h2>{p.name}</h2><button onclick={()=>draft.policies=draft.policies.filter((_,j)=>j!==i)}>Remove policy</button></div><div class="form-grid"><label>Name<input bind:value={p.name}/></label><label>Event types · comma-separated<input value={p.event_types.join(', ')} oninput={e=>{p.event_types=e.currentTarget.value.split(',').map(s=>s.trim());draft={...draft};}}/></label><label>Threshold<input type="number" min="1" max="1000" bind:value={p.threshold}/></label><label>Rolling window (seconds)<input type="number" min="1" max="86400" bind:value={p.window_seconds}/></label><label>Base ban duration (seconds)<input type="number" min="1" max="604800" bind:value={p.ban_seconds}/></label><label class="check"><input type="checkbox" checked={!!p.ban_escalation} onchange={e=>{p.ban_escalation=e.currentTarget.checked?{multiplier:2,max_ban_seconds:Math.max(Number(p.ban_seconds),86400),reset_after_seconds:604800}:null;draft={...draft};}}/> Escalate repeat bans</label>{#if p.ban_escalation}<label>Repeat ban multiplier<input type="number" min="2" max="10" bind:value={p.ban_escalation.multiplier}/></label><label>Maximum ban (seconds)<input type="number" min={p.ban_seconds} max="604800" bind:value={p.ban_escalation.max_ban_seconds}/></label><label>Reset after last ban (seconds)<input type="number" min="1" max="31536000" bind:value={p.ban_escalation.reset_after_seconds}/></label>{/if}<label class="check"><input type="checkbox" bind:checked={p.enabled}/> Detection enabled</label><label class="check"><input type="checkbox" bind:checked={p.observe_only}/> Observe-only policy</label></div><p class="help">Evidence: {!dirty&&detail?.service.revision===draft.revision?detail?.policy_health[p.id]||'waiting':'configuration changed / waiting'}. Status: {!draft.enabled||!p.enabled?'Disabled':draft.observe_only?'Observe only · service override':p.observe_only?'Observe only · this policy':!snapshot?.automatic?'Detection enabled · global automatic bans off':!snapshot?.blocking?'Detection enabled · global blocking off':'Enforcement requested · source warm-up and health apply'}. A source error clears all service policy windows.</p><p class="help">Observe-only policy suppresses new bans from this policy. Observe-only service overrides every policy. Both must be off to allow new bans. Observations appear on Overview; threshold decisions appear in Decisions &amp; Bans.</p>{#if p.ban_escalation}<p class="help">Each new ban for the same service, policy, and IP multiplies the duration, up to the maximum. The sequence resets after the configured interval since its last ban and survives restarts. Observe-only decisions and attempts during an active ban do not increase it.</p>{/if}</section>{/each}
    {:else if tab==='Decisions & Bans'}
      <section class="panel"><div class="title"><h2>Observed decisions & attributed bans</h2><a href="#firewall">Manage applied rules ↗</a></div><div class="scroll"><table><thead><tr><th>Decision time</th><th>IP / scope</th><th>Service / policy</th><th>Evidence</th><th>Status</th><th>Duration / rule / expiry</th></tr></thead><tbody>{#each detail?.decisions||[] as d}<tr><td>{time(d.hit.at)}</td><td>{d.hit.source_ip}<small>Whole source IP</small></td><td>{d.hit.service_name}<button class="link" onclick={()=>{selectedEvent={...d.hit.evidence,policy_id:d.hit.policy_id};tab='Overview';}}>{d.hit.policy_name}</button></td><td>{d.hit.count} events / {d.hit.window_seconds}s<details><summary>Trigger evidence</summary><pre>{JSON.stringify(d.hit.evidence,null,2)}</pre></details></td><td><span class="badge" class:danger={snapshot?.blocking&&d.rule?.applied&&d.rule?.enabled&&!allowed(d.hit.source_ip)&&(!d.rule.expires||d.rule.expires>Date.now()/1000)}>{decisionStatus(d)}</span>{#if d.rule?.error}<small class="warning">{d.rule.error}</small>{/if}</td><td>{d.hit.ban_seconds}s {d.rule_id?'ban':'base duration · no new ban'}<small>{d.rule_id?`#${d.rule_id}`:'—'}</small><small>{time(d.rule?.expires)}</small></td></tr>{/each}</tbody></table></div><p class="help">Latest 200 threshold decisions, including observations that created no ban. Observe-only, allowlisted, warm-up, and suspended decisions create no rule. Turning on observe-only, disabling, or deleting a service leaves existing rules to expire independently. Packet detector bans are controlled separately in Firewall.</p></section>
    {:else if tab==='Settings'}
      <section class="panel"><div class="title"><h2>Service settings</h2></div><div class="form-grid"><label>Name<input bind:value={draft.name} maxlength="128"/></label><label class="wide">Description<textarea rows="3" bind:value={draft.description} maxlength="2048"></textarea></label><label class="check"><input type="checkbox" bind:checked={draft.enabled}/> Detection enabled</label><label class="check"><input type="checkbox" bind:checked={draft.observe_only}/> Observe-only service</label></div><p class="help">Enforcement scope: entire source IP across all ports. Service identity is attribution, not packet scope. XDP does not distinguish applications sharing a port.</p><p class="help">Observe-only service prevents new bans from every policy while continuing log collection and detection. Events appear on Overview; threshold decisions appear in Decisions &amp; Bans. Existing bans remain until expiry or removal in Firewall. Packet detector bans are controlled separately in Firewall.</p><p class="help">To enforce, turn off service and policy observe-only flags, review evidence, and enable global automatic mode in <a href="#firewall">Firewall</a>. Management ranges, global allowlists, emergency disable, and health checks always apply.</p><p class="help">New file sources begin at the current end of the file. Restart and configuration changes restart policy warm-up. Journal and file inputs remain bounded; unavailability is shown on Overview.</p>{#if draft.id}<div class="inspect"><button class="danger" disabled={busy} onclick={remove}>{deleteArmed?'Confirm delete service':'Delete service'}</button>{#if deleteArmed}<button onclick={()=>deleteArmed=false}>Cancel</button><p>Deletes this configuration. Independent rules and this service’s existing bans remain until their own expiry.</p>{/if}</div>{/if}</section>
    {/if}
  {/if}
</div>
<style>
  .toolbar,.title,nav{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px}.toolbar h2{margin-right:auto}.title{padding:20px;margin:0;border-bottom:1px solid #edf1f3;justify-content:space-between}nav{border-bottom:1px solid #dbe3e6;padding-bottom:14px}nav .active{background:#e5f3f0;border-color:#82b9ad}.panel{background:white;border:1px solid #e0e7eb;border-radius:9px;margin-bottom:20px;overflow:hidden}h2{font-size:16px;margin:0}h3{font-size:14px}small{display:block;margin-top:5px}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}td,th{padding:15px;border-bottom:1px solid #edf1f3;vertical-align:top}th{background:#fafcfc;color:#8094a1;text-transform:uppercase;font-size:10px}.scroll{overflow:auto;max-height:520px}.form-grid{padding:20px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:start}.wide{grid-column:1/-1}.check{flex-direction:row;align-items:center;align-self:center}.check input{min-width:0}.filter{margin:0 20px 16px;border:1px solid #e0e7eb;border-radius:7px}.filter .toolbar{padding:16px 16px 0;margin-bottom:0}.filter .toolbar strong{margin-right:auto}.add{margin:0 20px 20px}.help{margin:18px 20px;font-size:12px;line-height:1.6;color:#738895}.inspect,.health{padding:20px;border-top:1px solid #edf1f3}.health .badge{margin-left:12px}.badge{display:inline-block;font-size:11px;padding:5px 8px;border-radius:4px;background:#eef2f5;color:#526978}.warning{color:#9d681c;background:#fff6e5;padding:9px}.danger{color:#ac3d3d;background:#fff2f2;border-color:#e2b9b9}.muted{opacity:.6}.link{background:none;border:0;padding:0;color:#247768;text-decoration:underline;text-align:left}.primary{background:#168b79;color:white}.notice{padding:12px;background:#edf3f6;color:#476475;font-size:12px}.error{padding:12px;border:1px solid #e1b7b7;background:#fff2f2;color:#ac3d3d}textarea{font:12px/1.6 ui-monospace,monospace;width:100%;min-width:0;resize:vertical;border:1px solid #d3dfe3;border-radius:6px;padding:12px;color:#263b47}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.6 ui-monospace,monospace;max-height:300px;overflow:auto}.evidence{max-width:350px;overflow-wrap:anywhere}.inspect a{margin-left:16px}a{color:#247768}details summary{cursor:pointer}button{font-size:12px}@media(max-width:900px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.toolbar{gap:8px}.title{align-items:start}}
</style>
